// Company boilerplate content
const boilerplate = {
  short_50: "Sako is a design subscription service for SaaS companies. Ship design work in 48h without the hiring overhead.",

  medium_100: "Sako is a design subscription service built for SaaS companies who need quality design work without the overhead of hiring. Our 48-hour turnaround and unlimited revisions model helps startups and scale-ups move faster than their competition.",

  long_250: `Sako is a design subscription service built specifically for SaaS companies who need consistent, high-quality design work without the overhead of hiring full-time designers or managing freelancers.

Our model is simple: unlimited design requests, delivered in 48 hours, with unlimited revisions included. No contracts, no hiring headaches, no back-and-forth with unreliable contractors.

We serve SaaS founders, product teams, and marketing leaders who need to ship fast. Our clients include early-stage startups moving quickly to product-market fit and growth-stage companies scaling their design operations.

Founded in 2024, Sako operates as a distributed team of senior designers who specialize in SaaS design systems, landing pages, marketing collateral, and motion graphics.`
};

return { json: { boilerplate } };

// Founder bio content
const founderBio = {
  short_50: "Your Founder is the founder of Sako, a design subscription service for SaaS companies.",

  long_150: `Your Founder is the founder of Sako, a design subscription service for SaaS companies. Before Sako, he built and scaled design operations at multiple SaaS startups, experiencing firsthand the pain of hiring and managing design talent.

Koushik started Sako to solve the problem he kept encountering: SaaS companies need great design but can't justify (or wait for) full-time hires. His background in both design and product makes him uniquely positioned to understand what SaaS teams actually need.`
};

return { json: { founderBio } };

// Compile media kit
const boilerplate = $('Fetch Boilerplate').item.json.boilerplate;
const founderBio = $('Fetch Founder Bio').item.json.founderBio;
const proofPoints = ($('Fetch Proof Points').all() || []).slice(0, 3).map(p => p.json);

const mediaKit = {
  generated_at: new Date().toISOString(),

  company: {
    name: 'Sako',
    website: 'https://trysako.com',
    founded: '2024',
    boilerplate
  },

  founder: {
    name: 'Your Founder',
    title: 'Founder',
    email: 'hello@example.com',
    linkedin: 'https://linkedin.com/in/koushikvenkatesan',
    bio: founderBio
  },

  assets: {
    logo_svg: 'https://trysako.com/assets/logo.svg',
    logo_png_dark: 'https://trysako.com/assets/logo-dark.png',
    logo_png_light: 'https://trysako.com/assets/logo-light.png',
    founder_headshot: 'https://trysako.com/assets/koushik-headshot.jpg',
    product_screenshots: [
      'https://trysako.com/assets/screenshot-dashboard.png',
      'https://trysako.com/assets/screenshot-task.png',
      'https://trysako.com/assets/screenshot-review.png'
    ]
  },

  proof_points: proofPoints.map(p => ({
    client: p.client || 'Client',
    result: p.result || p.headline,
    metric: p.metric || ''
  })),

  fact_sheet: {
    model: 'Design subscription',
    pricing: 'Starting at $X/month',
    turnaround: '48 hours',
    revisions: 'Unlimited',
    contract: 'Month-to-month'
  }
};

return { json: mediaKit };

// Generate markdown files for media kit
const kit = $input.first().json;

const boilerplateMd = `# Sako Company Boilerplate

## 50 Words
${kit.company.boilerplate.short_50}

## 100 Words
${kit.company.boilerplate.medium_100}

## 250 Words
${kit.company.boilerplate.long_250}
`;

const founderBioMd = `# Founder Bio - Your Founder

## 50 Words
${kit.founder.bio.short_50}

## 150 Words
${kit.founder.bio.long_150}

## Contact
- Email: ${kit.founder.email}
- LinkedIn: ${kit.founder.linkedin}
`;

const proofPointsMd = `# Proof Points

${kit.proof_points.map((p, i) => `## ${i + 1}. ${p.client}\n${p.result}\n${p.metric ? `*Metric: ${p.metric}*` : ''}`).join('\n\n')}
`;

const factSheetMd = `# Sako Fact Sheet

| Attribute | Value |
|-----------|-------|
| Model | ${kit.fact_sheet.model} |
| Pricing | ${kit.fact_sheet.pricing} |
| Turnaround | ${kit.fact_sheet.turnaround} |
| Revisions | ${kit.fact_sheet.revisions} |
| Contract | ${kit.fact_sheet.contract} |

## Assets
- Logo (SVG): ${kit.assets.logo_svg}
- Logo (PNG Dark): ${kit.assets.logo_png_dark}
- Logo (PNG Light): ${kit.assets.logo_png_light}
- Founder Headshot: ${kit.assets.founder_headshot}
`;

return {
  json: {
    ...kit,
    files: {
      'boilerplate.md': boilerplateMd,
      'founder-bio.md': founderBioMd,
      'proof-points.md': proofPointsMd,
      'fact-sheet.md': factSheetMd
    }
  }
};

